export function createExperience({openView,copyText,download,toast}){
 const $=id=>document.getElementById(id),main=document.querySelector('main');
 const home=document.createElement('section');home.id='home';home.className='view mansour-home';home.hidden=true;
 home.innerHTML=`<div class="welcome-copy"><span class="eyebrow">به فضای مطالعهٔ خودت خوش آمدی</span><h2>هر آیه،<br>آغاز یک کشف تازه.</h2><p>قرآن، تفسیر و یادداشت‌هایت؛ در کتابخانه‌ای آرام و همیشه همراه.</p><div class="welcome-actions"><button data-go="reader" class="primary">ادامهٔ مطالعه ←</button><button data-go="notebook">باز کردن دفتر من</button></div><div class="home-shortcuts"><button data-go="library"><strong>کتابخانه</strong><span>متن و تصویر منابع</span></button><button data-go="words"><strong>واژه‌ها و ریشه‌ها</strong><span>دقیق‌تر بخوان</span></button><button data-go="packs"><strong>دریافت کتاب‌ها</strong><span>بسته‌های مطالعهٔ آفلاین</span></button></div><p class="creator-line">پدیدآورنده: <strong>امیررضا نصیری</strong></p></div><figure class="welcome-art"><img src="mansour-brand.png" alt="نشان جامع التفاسیر منصور؛ قرآن و کتاب‌های تفسیر با طرح سبز و طلایی"><figcaption>جامع التفاسیر منصور · همراه پژوهش شما</figcaption></figure>`;
 main.append(home);
 const community=document.createElement('section');community.id='community';community.className='view';community.hidden=true;
 community.innerHTML=`<div class="section-intro"><span class="eyebrow">با همراهی شما</span><h2>دربارهٔ منصور و همراهی با برنامه</h2><p>پدیدآورنده: <strong>امیررضا نصیری</strong></p></div><div class="community-grid"><article class="source-card support-card"><h3>حمایت از ادامهٔ مسیر منصور</h3><p>اگر منصور در مطالعه و پژوهش همراهت بوده، می‌توانی به‌صورت اختیاری از توسعهٔ آن حمایت کنی.</p><label>شماره کارت</label><output class="support-number" dir="ltr">5022 2915 1461 8634</output><p>به نام امیررضا نصیری</p><button id="copy-support-card" class="primary">کپی شماره کارت</button><p class="footnote">واریز از طریق برنامهٔ بانکی خودت انجام می‌شود. این صفحه پرداخت انجام نمی‌دهد و اطلاعات بانکی دریافت نمی‌کند.</p></article><form id="feedback-form" class="source-card"><h3>منصور را چطور تجربه کردی؟</h3><label for="feedback-rating">امتیاز شما</label><select id="feedback-rating" required><option value="">یک امتیاز انتخاب کن</option><option value="5">۵ · عالی</option><option value="4">۴ · خوب</option><option value="3">۳ · متوسط</option><option value="2">۲ · نیاز به بهبود</option><option value="1">۱ · ضعیف</option></select><label for="feedback-text">پیشنهاد یا تجربهٔ شما</label><textarea id="feedback-text" maxlength="3000" placeholder="دوست داری چه چیزی بهتر شود؟"></textarea><p class="footnote">نظر فقط روی همین دستگاه ذخیره می‌شود و خودکار ارسال نمی‌شود. می‌توانی فایل خروجی را خودت به اشتراک بگذاری.</p><div class="pack-actions"><button type="submit" class="primary">ذخیرهٔ نظر روی دستگاه</button><button type="button" id="feedback-export">دریافت فایل نظر</button></div><p id="feedback-status" role="status"></p></form></div>`;
 main.append(community);
 const trigger=document.createElement('button');trigger.id='tools-menu';trigger.type='button';trigger.className='tools-trigger';trigger.setAttribute('aria-label','باز کردن ابزارها و حالت‌ها');trigger.setAttribute('aria-haspopup','dialog');trigger.setAttribute('aria-expanded','false');trigger.innerHTML='<svg width="23" height="23" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M4 6h16M4 12h16M4 18h16"/></svg>';
 document.querySelector('.topbar').prepend(trigger);
 const dialog=document.createElement('dialog');dialog.id='tools-drawer';dialog.className='tools-drawer';dialog.setAttribute('aria-labelledby','tools-title');dialog.innerHTML='<div class="drawer-heading"><h2 id="tools-title">ابزارها و حالت‌ها</h2><button id="close-tools" aria-label="بستن منو">×</button></div><img class="drawer-logo" src="mansour-brand.png" alt="نشان منصور"><div id="drawer-items"></div><p class="footnote">جامع التفاسیر منصور<br>پدیدآورنده: امیررضا نصیری</p>';
 document.body.append(dialog);
 const entries=[['home','خانهٔ منصور'],['reader','مطالعه و تطبیق'],['library','کتابخانهٔ منصور'],['notebook','دفتر یادداشت'],['notes','یادداشت‌ها و نشان‌های آیات'],['words','واژه‌ها و ریشه‌ها'],['packs','دانلود و افزودن کتاب'],['settings','رنگ‌بندی و حالت مطالعه'],['community','پدیدآورنده، حمایت و نظرسنجی'],['sources','منابع و پوشش محتوا']];
 for(const [id,title]of entries){const b=document.createElement('button');b.textContent=title;b.onclick=()=>{dialog.close();openView(id);$('page-title').focus();};$('drawer-items').append(b);}
 trigger.onclick=e=>{dialog.dataset.keyboard=String(e.detail===0);dialog.showModal();trigger.setAttribute('aria-expanded','true');};$('close-tools').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{trigger.setAttribute('aria-expanded','false');trigger.focus();});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
 $('page-title').tabIndex=-1;home.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>openView(b.dataset.go));
 const homeButton=document.createElement('button');homeButton.className='top-brand';homeButton.innerHTML='<img src="mansour-brand.png" alt=""><span>منصور</span>';homeButton.setAttribute('aria-label','خانهٔ منصور');homeButton.onclick=()=>openView('home');document.querySelector('.top-actions').prepend(homeButton);
 $('copy-support-card').onclick=async()=>{try{await copyText('5022291514618634');toast('شماره کارت کپی شد.');}catch{toast('کپی خودکار ممکن نشد؛ شماره کارت را انتخاب و کپی کنید.');}};
 const feedbackKey='mansour-feedback-v1';try{const stored=JSON.parse(localStorage.getItem(feedbackKey)||'null');if(stored){$('feedback-rating').value=String(stored.rating);$('feedback-text').value=String(stored.comment||'').slice(0,3000);$('feedback-status').textContent='نظر قبلی روی همین دستگاه ذخیره شده است.';}}catch{$('feedback-status').textContent='نظر قبلی قابل خواندن نیست.';}
 function feedback(){return {format:feedbackKey,rating:Number($('feedback-rating').value),comment:$('feedback-text').value,updatedAt:new Date().toISOString()};}
 $('feedback-form').onsubmit=e=>{e.preventDefault();try{localStorage.setItem(feedbackKey,JSON.stringify(feedback()));$('feedback-status').textContent='نظر روی این دستگاه ذخیره شد؛ ارسال نشده است.';}catch{$('feedback-status').textContent='ذخیره نشد؛ فایل نظر را دریافت کنید.';}};
 $('feedback-export').onclick=()=>{if(!$('feedback-form').reportValidity())return;download('mansour-feedback.json',JSON.stringify(feedback(),null,2),'application/json');};
}
